const body = $input.first()?.json?.body ?? $input.first()?.json ?? {};
const action = (body.action || 'list_inbox').toLowerCase();
const allowed = ['draft','send','list_inbox'];
if (!allowed.includes(action)) {
  throw new Error('Invalid action. Must be one of: ' + allowed.join(', '));
}
const to        = body.to      || '';
const subject   = body.subject || '';
const bodyText  = body.body    || '';
const cc        = body.cc      || '';
const count     = Number(body.count) || 10;
const confirmed = body.confirmed === true || body.confirmed === 'true';
if (action === 'send' && !confirmed) {
  throw new Error('send requires confirmed=true — user must explicitly approve sending email');
}
return [{ json: { action, to, subject, bodyText, cc, count, confirmed } }];

const raw = $input.first()?.json?.stdout ?? '';
let validation;
try { validation = JSON.parse(raw); } catch { validation = { allowed: true }; }
if (validation.allowed === false) {
  throw new Error('Safety validation blocked email operation: ' + (validation.reason || 'policy'));
}
const params = $('Parse Parameters').first().json;
return [{ json: params }];

const raw = $input.first()?.json?.stdout ?? $input.first()?.json?.stderr ?? '';
let result;
try { result = JSON.parse(raw); } catch { result = { success: false, error: raw || 'No output from EmailOps.ps1' }; }
return [{ json: result }];
